"""Typed error taxonomy shared by API, CLI and validators."""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any


@dataclass
class DcsError(Exception):
    code: str
    message: str
    http_status: int = 400
    details: list[dict[str, Any]] = field(default_factory=list)

    def __str__(self) -> str:  # pragma: no cover - trivial
        return f"{self.code}: {self.message}"

    def to_body(self) -> dict[str, Any]:
        return {"error": {"code": self.code, "message": self.message, "details": self.details}}


# Authentication / tenancy
AUTH_NOT_CONFIGURED = "AUTH_NOT_CONFIGURED"
AUTH_REQUIRED = "AUTH_REQUIRED"
AUTH_INVALID = "AUTH_INVALID"
TENANT_MISMATCH = "TENANT_MISMATCH"

# Request shape
REQUEST_INVALID = "REQUEST_INVALID"
# Plan validity (schema + semantic)
PLAN_SCHEMA_INVALID = "PLAN_SCHEMA_INVALID"
PLAN_INVALID = "PLAN_INVALID"
SCHEMA_REF_UNRESOLVABLE = "SCHEMA_REF_UNRESOLVABLE"

# Graph invariants (I1-I4 and structural)
BINDING_UNAUTHORIZED = "BINDING_UNAUTHORIZED"  # I1
BINDING_DEPENDS_MISMATCH = "BINDING_DEPENDS_MISMATCH"  # I2
SOURCE_SCOPE_VIOLATION = "SOURCE_SCOPE_VIOLATION"  # I3
SOURCE_UNKNOWN = "SOURCE_UNKNOWN"  # I3
CYCLE_DETECTED = "CYCLE_DETECTED"  # I4
DUPLICATE_NODE_ID = "DUPLICATE_NODE_ID"  # I4
DANGLING_DEPENDENCY = "DANGLING_DEPENDENCY"  # I4
EDGE_DEPENDS_MISMATCH = "EDGE_DEPENDS_MISMATCH"  # I4
BINDING_PATH_INVALID = "BINDING_PATH_INVALID"
BINDING_DUPLICATE_ALIAS = "BINDING_DUPLICATE_ALIAS"
BINDING_SCHEMA_MISMATCH = "BINDING_SCHEMA_MISMATCH"
DUPLICATE_SOURCE_ID = "DUPLICATE_SOURCE_ID"
# P01R additions (R1 fragment binding, R2 edge-set exactness)
FRAGMENT_REF_MALFORMED = "FRAGMENT_REF_MALFORMED"
FRAGMENT_VERSION_UNKNOWN = "FRAGMENT_VERSION_UNKNOWN"
FRAGMENT_NOT_REGISTERED = "FRAGMENT_NOT_REGISTERED"
EDGE_DUPLICATE = "EDGE_DUPLICATE"
EDGE_UNEXPECTED = "EDGE_UNEXPECTED"
DEPENDS_ON_DUPLICATE = "DEPENDS_ON_DUPLICATE"
TOPOLOGICAL_ORDER_UNSTABLE = "TOPOLOGICAL_ORDER_UNSTABLE"
ZERO_MODEL_HAS_MODEL_POLICY = "ZERO_MODEL_HAS_MODEL_POLICY"

# P02 additions
SOURCE_SCOPE_UNBOUND = "SOURCE_SCOPE_UNBOUND"  # I3: scope entry no fragment ref binds (F1)
CANONICAL_KEY_COLLISION = "CANONICAL_KEY_COLLISION"  # F4: two keys NFC-normalize to the same key
# Source registry (POST /v1/sources, GET /v1/sources/...)
STORE_NOT_CONFIGURED = "STORE_NOT_CONFIGURED"
SOURCE_MIME_UNSUPPORTED = "SOURCE_MIME_UNSUPPORTED"
SOURCE_TOO_LARGE = "SOURCE_TOO_LARGE"
SOURCE_ENCODING_INVALID = "SOURCE_ENCODING_INVALID"
SOURCE_CONTENT_INVALID = "SOURCE_CONTENT_INVALID"
SOURCE_ID_INVALID = "SOURCE_ID_INVALID"
SOURCE_NOT_FOUND = "SOURCE_NOT_FOUND"
SOURCE_VERSION_UNKNOWN = "SOURCE_VERSION_UNKNOWN"  # compile: claimed (file_id, version, content_hash) not registered
SOURCE_IMMUTABLE = "SOURCE_IMMUTABLE"  # mutation/delete refused

# Compile-level unresolved statuses (returned inside PlanIR.unresolved, HTTP 200)
UNSUPPORTED_INTENT = "UNSUPPORTED_INTENT"
SOURCE_COUNT_MISMATCH = "SOURCE_COUNT_MISMATCH"
COMPARISON_DIMENSION_MISSING = "COMPARISON_DIMENSION_MISSING"
